{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket has no logging",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket storing CloudTrail logs has no logging enabled, making it difficult to track access and changes to the logs themselves."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket has no object versioning",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket storing CloudTrail logs lacks object versioning, which could lead to loss of historical log data in case of accidental deletion or overwrite."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"cloudtrail_logs\" {\n  bucket        = \"smart-city-parking-management-system-s3-cloudtrail-${random_string.cloudtrail_suffix.result}\"\n  force_destroy = true\n\n  versioning {\n    enabled = true\n  }\n\n  logging {\n    target_bucket = \"smart-city-parking-management-system-s3-cloudtrail-${random_string.cloudtrail_suffix.result}-logs\"\n    target_prefix = \"/\"\n  }\n}",
  "fix_summary": "Enabled versioning on the S3 bucket and added logging configuration to track access and changes to CloudTrail logs."
}
